#!/usr/bin/env node
/**
 * PRJ226 v3.0: Vault Indexer Script with SHA-256 Token Optimization (Trap 3 Fix)
 *
 * Reads OKF Markdown files from ./vault directory (generated by OpenWiki Personal Brain).
 * Computes SHA-256 hash of content before calling Gemini Embedding API.
 * If hash matches Neon DB → SKIPS call to save 100% of API tokens.
 * If hash differs or file is new → calls Gemini Embedding API & upserts into Neon.
 *
 * Run: node scripts/index-vault-to-neon.js
 * Env: DATABASE_URL, GOOGLE_API_KEY, VAULT_DIR
 */

const { neon } = require('@neondatabase/serverless');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Config ───────────────────────────────────────────────────────────────────

const DATABASE_URL = process.env.DATABASE_URL;
const GOOGLE_API_KEY = process.env.GOOGLE_API_KEY;
const VAULT_DIR = process.env.VAULT_DIR || './vault';

if (!DATABASE_URL) {
  console.error('❌ DATABASE_URL environment variable is required');
  process.exit(1);
}

if (!GOOGLE_API_KEY) {
  console.error('❌ GOOGLE_API_KEY environment variable is required');
  process.exit(1);
}

const sql = neon(DATABASE_URL);

// ─── SHA-256 Content Hash Calculator ──────────────────────────────────────────

function computeSHA256(content) {
  return crypto.createHash('sha256').update(content).digest('hex');
}

// ─── Embedding via Gemini REST API ────────────────────────────────────────────

async function generateEmbedding(text) {
  const truncated = text.substring(0, 3000);
  const response = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/text-embedding-004:embedContent?key=${GOOGLE_API_KEY}`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'models/text-embedding-004',
        content: { parts: [{ text: truncated }] },
      }),
    }
  );

  if (!response.ok) {
    throw new Error(`Embedding API error ${response.status}: ${await response.text()}`);
  }

  const data = await response.json();
  return data.embedding.values;
}

// ─── OKF Front Matter Parser ──────────────────────────────────────────────────

function parseOKFDocument(filePath, rawMarkdown) {
  const frontMatterMatch = rawMarkdown.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);

  let title = path.basename(filePath, '.md');
  let tags = [];
  let content = rawMarkdown;

  if (frontMatterMatch) {
    const yamlSection = frontMatterMatch[1];
    content = frontMatterMatch[2].trim();

    const titleMatch = yamlSection.match(/^title:\s*["']?(.+?)["']?\s*$/m);
    const tagsMatch = yamlSection.match(/^tags:\s*\[(.+?)\]\s*$/m);

    if (titleMatch) title = titleMatch[1];
    if (tagsMatch) tags = tagsMatch[1].split(',').map((t) => t.trim().replace(/["']/g, ''));
  }

  return { title, tags, content };
}

// ─── Upsert into Neon ─────────────────────────────────────────────────────────

async function upsertWikiEntry(githubPath, title, content, contentHash, tags, embedding) {
  const embeddingLiteral = `[${embedding.join(',')}]`;
  await sql`
    INSERT INTO knowledge_wiki (title, content, content_hash, embedding, github_path, tags, synthesized_at)
    VALUES (${title}, ${content}, ${contentHash}, ${embeddingLiteral}::vector, ${githubPath}, ${tags}, now())
    ON CONFLICT (github_path) DO UPDATE SET
      title = EXCLUDED.title,
      content = EXCLUDED.content,
      content_hash = EXCLUDED.content_hash,
      embedding = EXCLUDED.embedding,
      tags = EXCLUDED.tags,
      updated_at = now()
  `;
}

// ─── Main ─────────────────────────────────────────────────────────────────────

async function main() {
  console.log(`📁 Reading vault from: ${VAULT_DIR}`);

  if (!fs.existsSync(VAULT_DIR)) {
    console.log('⚠️  Vault directory does not exist. Skipping indexing.');
    return;
  }

  const files = fs.readdirSync(VAULT_DIR).filter((f) => f.endsWith('.md'));
  console.log(`📄 Found ${files.length} Markdown files to evaluate.`);

  // Load existing content hashes from Neon
  const existingRows = await sql`
    SELECT github_path, content_hash FROM knowledge_wiki
  `.catch(() => []);

  const hashMap = new Map();
  for (const row of existingRows) {
    hashMap.set(row.github_path, row.content_hash);
  }

  let indexed = 0;
  let skipped = 0;
  let errors = 0;

  for (const file of files) {
    const filePath = path.join(VAULT_DIR, file);
    const githubPath = `vault/${file}`;

    try {
      const rawMarkdown = fs.readFileSync(filePath, 'utf-8');
      const { title, tags, content } = parseOKFDocument(filePath, rawMarkdown);

      if (!content.trim()) {
        console.log(`  ⏭️  Skipping empty file: ${file}`);
        skipped++;
        continue;
      }

      // Compute SHA-256 hash
      const contentHash = computeSHA256(rawMarkdown);
      const existingHash = hashMap.get(githubPath);

      // Idempotency check: if hash matches, skip Gemini API embedding call!
      if (existingHash && existingHash === contentHash) {
        console.log(`  ⚡ Unchanged (SHA-256 match): ${file} → Skipped API call.`);
        skipped++;
        continue;
      }

      console.log(`  🧠 Embedding & Indexing: "${title}" (${content.length} chars, new hash: ${contentHash.substring(0, 8)}...)...`);
      const embedding = await generateEmbedding(`${title}\n\n${content}`);

      await upsertWikiEntry(githubPath, title, content, contentHash, tags, embedding);
      console.log(`  ✅ Indexed: ${file}`);
      indexed++;

      // Rate limit throttle
      await new Promise((r) => setTimeout(r, 500));
    } catch (err) {
      console.error(`  ❌ Error indexing ${file}:`, err.message);
      errors++;
    }
  }

  console.log(`\n📊 Vault Indexing Summary:`);
  console.log(`   ✅ Indexed (Updated/New): ${indexed}`);
  console.log(`   ⚡ Skipped (SHA-256 Match): ${skipped}`);
  console.log(`   ❌ Errors:                 ${errors}`);
  console.log(`   📚 Total Vault Files:       ${files.length}`);
}

main().catch((err) => {
  console.error('💥 Fatal error in vault indexer:', err);
  process.exit(1);
});
